#define remove_dupes(x) sort(all(x)); (x).resize(distance((x).begin(), unique(all(x))));

using namespace std;
using namespace __gnu_pbds;

template<typename T>
using ordered_set_type = tree<T, null_type, less<T>, rb_tree_tag, tree_order_statistics_node_update>;

typedef long long LL;
typedef pair<int,int> PII;
typedef pair<LL,LL> PLL;
typedef vector<PII> VPII;
typedef vector<PLL> VPLL;
typedef vector<LL> VLL;
typedef vector<int> VI;
typedef vector<string> VS;
typedef vector<char> VC;
typedef long double LD;
typedef pair<LD,LD> PLD;
typedef vector<LD> VLD;
typedef vector<PLD> VPLD;

template<class T> void debug_output(const char *s, T h){ cerr << s << " = " << h << endl; }
template<class T, class... Args> void debug_output(const char *s, T h, Args... a) {
  while(*s != ',') cerr << *s++;
  cerr << " = " << h << ", "; debug_output(s+1, a...);
}

#ifdef LOCAL
#define debug(...) debug_output(#__VA_ARGS__, __VA_ARGS__)
#else
#define debug(...)
#define cerr if(0) cout
#endif

const int MAXN = (1<<20)+7;
const int MAXK = 20;
const int INF = (1e9)+7;
const LL LLINF = ((LL)1e18)+7LL;
const LD EPS = 1e-9;
const LL MOD = 1e9+7;

int grid_vals[MAXK][MAXK];
int elo_map_vals[MAXK][MAXK];
int mask_map_vals[MAXN];

LL dp_vals[MAXN][2];

int compute_mask_value(VPII edges, bool flag) {
    int mask_value = 0;
    for (int i = 0; i < size_of(edges); i++)
        for (int j = i + 1; j < size_of(edges); j++)
            if (edges[i].first != edges[j].first && edges[i].second != edges[j].second)
                for (int k = j + 1; k < size_of(edges); k++)
                    if (edges[i].first != edges[k].first && edges[j].first != edges[k].first
                        && edges[i].second != edges[k].second && edges[j].second != edges[k].second)
                        mask_value |= mask_map_vals[(flag ? 126 : 0) ^ ((1 << edges[i].second) + (1 << edges[j].second) + (1 << edges[k].second))];
    return mask_value;
}

LL compute_power(LL base, LL exponent) {
    if (exponent == 0) return 1;
    LL half_pow = compute_power(base, exponent / 2);
    LL result = (half_pow * half_pow) % MOD;
    if (exponent & 1) result = (result * base) % MOD;
    return result;
}

int main() {
    sync_stdio
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            cin >> grid_vals[i][j];
    int counter = 0;
    for (int i = 1; i <= 6; i++)
        for (int j = i + 1; j <= 6; j++)
            for (int k = j + 1; k <= 6; k++)
                mask_map_vals[(1 << i) ^ (1 << j) ^ (1 << k)] = (1 << counter++);
    for (int i = n + 1; i <= 6; i++)
        grid_vals[i][i] = 100;
    VPII edges;
    n = 6;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            edges.push_back({i, j});
    LL inv_100 = compute_power(100, MOD - 2);
    for (int k = 0; k < 2; k++)
        for (int mask_idx = 0; mask_idx < (1 << 18); mask_idx++) {
            LL prob = 1;
            VPII selected_edges;
            for (int j = 0; j < 18; j++)
                if ((1 << j) & mask_idx) {
                    prob = (prob * grid_vals[edges[j + k * 18].first][edges[j + k * 18].second]) % MOD * inv_100 % MOD;
                    selected_edges.push_back(edges[j + k * 18]);
                } else {
                    prob = (prob * (100 - grid_vals[edges[j + k * 18].first][edges[j + k * 18].second])) % MOD * inv_100 % MOD;
                }
            int current_mask = compute_mask_value(selected_edges, k);
            dp_vals[current_mask][k] = (dp_vals[current_mask][k] + prob) % MOD;
        }
    LL final_result = 1;
    for (int i = 0; i < 20; i++)
        for (int j = 0; j < (1 << 20); j++)
            if ((1 << i) & j) {
                dp_vals[j][0] = (dp_vals[j][0] + dp_vals[j ^ (1 << i)][0]) % MOD;
            }
    for (int i = 0; i < (1 << 20); i++) {
        final_result = (final_result - dp_vals[i][0] * dp_vals[((1 << 20) - 1) ^ i][1]) % MOD;
    }
    final_result = (final_result + MOD) % MOD;
    cout << final_result;
    return 0;
}
